// Demo: Signature Adaptive B-Tree Rebalancing — fragmentation score decides the rebuild plan
function frag(pages){var gaps=0;for(var i=1;i<pages.length;i++){if(pages[i]!==pages[i-1]+1)gaps++;}return gaps/Math.max(1,pages.length);}
var pages=[];for(var i=0;i<2;i++){pages.push(i*2+((1+i)%3));}
var f=frag(pages);
console.log('technique: Signature Adaptive B-Tree Rebalancing');console.log('pages: '+pages.length+', fragmentation: '+(f*100).toFixed(1)+'%');
console.log(f>0.35?'action: schedule online defragmentation':'action: leave the index as-is');

// Demo: Signature Learned Index Auto-Tuning — hot-key skew detection over 8 sampled keys
var keys={};for(var i=0;i<8;i++){var k='key-'+((i*7919+2)%15==0?'HOT':'c'+(i%50));keys[k]=(keys[k]||0)+1;}
var hot=Object.keys(keys).filter(function(k){return keys[k]>3;});
console.log('technique: Signature Learned Index Auto-Tuning');console.log('distinct keys: '+Object.keys(keys).length);
console.log('hot keys detected: '+hot.length+(hot.length?' ('+hot.slice(0,3).join(', ')+')':''));
console.log(hot.length?'action: split the hot partition':'action: no reshaping needed');

